 Title'=>'Titel van je webinar','Your Webinar URL'=>'Je webinar URL','Your WebinarIgnition SMTP settings have been migrated. You can find the new settings <a href="/wp-admin/admin.php?page=webinarignition_settings">here</a>'=>'Je WebinarIgnition SMTP instellingen zijn gemigreerd. Je kunt de nieuwe instellingen <a href="/wp-admin/admin.php?page=webinarignition_settings">hier</a> vinden','YOUR<br/>TIMEZONE'=>'UW<br/>TIMEZONE','{privacy_policy} | {imprint} | © Copyright {year} {site_title}'=>'{privacy_policy} | {imprint} | © Copyright {jaar} {site_title}']];
